package com.lankawings.servlet;
import com.lankawings.dao.*;import com.lankawings.model.*;import com.lankawings.util.Req;import jakarta.servlet.ServletException;import jakarta.servlet.annotation.WebServlet;import jakarta.servlet.http.*;import java.io.IOException;
/** Read-only passenger e-ticket view. Ticket creation happens through the one-click Mark Paid action. */
@WebServlet("/ticket") public class TicketServlet extends HttpServlet{@Override protected void doGet(HttpServletRequest r,HttpServletResponse s)throws ServletException,IOException{try{Booking b=new BookingDAO().find(Req.id(r,"bookingId","booking"));if(b==null||b.getUserId()!=Req.uid(r)){s.sendError(404);return;}Ticket t=new TicketDAO().findByBooking(b.getBookingId());r.setAttribute("booking",b);r.setAttribute("ticket",t);if(t==null)r.setAttribute("error","No e-ticket exists yet. Open My Reservations and use Mark Paid & View Ticket.");}catch(Exception e){Req.error(r,e);}r.getRequestDispatcher("/WEB-INF/views/ticket.jsp").forward(r,s);}}
